package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Move the loaded claim to its new status, refusing a change its status does not allow (or one
 *  another user's change got to first). Opening gives the claim the sheet's next number; voiding
 *  keeps it (a number is never reused). Opening records who opened it, and that user may not settle it; nor may the user who last edited it (SaveClaim records them). Settling fixes its due
 *  as its row shows it now: the bound figure, else live at the person's grade rate now in force on the claim's date,
 *  with the late charge as of today on it, at least the sheet's floor in force on its date, frozen in. A claim whose due (as shown) is above the sheet's proof threshold in force
 *  on the claim's date cannot be settled or approved while its proofs count is 0 (refused before the clerk limit is
 *  considered; no threshold, or a due of n/a, is within it). When a clerk (any user not made a steward)
 *  settles a claim whose due (as shown: bound by a statement, else live, plus any late charge) is above the sheet's
 *  clerk limit, it becomes PENDING instead (a due of n/a, or no limit, is within it). A steward other than the
 *  user who opened it or last edited it approves a PENDING claim (it becomes SETTLED, its due as its row shows it then — live, a
 *  PENDING claim is not bound by a statement — frozen in) or rejects it (OPEN again, bound again by the statement
 *  that bound it). A steward re-settles a SETTLED claim: it is frozen again at the figure it would have today as an
 *  OPEN claim bound by no statement (today's rates, grades, floor and late charge). A steward voids a SETTLED claim within 7 days of its settlement (its SETTLED date in the status log, by the sheet's today): it keeps its number and its frozen figure, which leaves every total. The new status is added to the claim's status log. A claim settled one at a time is settled by no batch. The rules are in {@link ClaimStatusChange}. */
public class SaveClaimStatus {
    public void save(@Val ClaimStatusInput input, @Val Claim loaded, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log, SettleBatchRepository batches,
            Out<ClaimResponse> saved)
            throws ClaimStatusNotAllowedException {
        saved.set(ClaimStatusChange.save(input, loaded, repository, people, rates, roles, settings, sheets, log));
        if (input.action().equals("settle")) {
            batches.settledAlone(loaded.sheetId(), loaded.id());
        }
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle of a claim due above the clerk
 *  limit makes it PENDING instead, until a steward approves it (SETTLED) or rejects it (OPEN again); a DRAFT, OPEN
 *  or PENDING claim may be VOID, and a steward may void a SETTLED one within 7 days of its settlement (checked in
 *  ClaimStatusChange). A DRAFT claim may be DELETED, and restored to a DRAFT on the same sheet-today (checked in
 *  ClaimStatusChange). A claim opened with a due above the sheet's review threshold in force on its date is REVIEW
 *  instead of OPEN, unnumbered, until a steward reviews it (OPEN, numbered then); a REVIEW claim may be VOID. Only
 *  OPEN, PENDING and SETTLED claims count toward the totals. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether a claim with this status counts toward the totals (and is bound by a statement). */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim with this status is still to be settled: OPEN or PENDING (it goes overdue, bears the late
     *  charge). */
    public boolean unsettled() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim with this status may move to the given one by opening, settling, voiding, deleting or
     *  restoring it (approving
     *  and rejecting a PENDING claim, and reviewing a REVIEW one, are checked on their own). */
    public boolean canBecome(ClaimStatus to) {
        return switch (to) {
            case OPEN -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == REVIEW;
            case REVIEW -> this == DRAFT;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }
}
